 "Errores frecuentes": "Erros frequentes",
 "<b style=\"font-size:26px;color:#d8504a\">Palabras vagas</b><br><span style=\"font-size:21px;color:#1f2430\">«Bien», «regular», «poco»: no se pueden observar.</span>": "<b style=\"font-size:26px;color:#d8504a\">Palavras vagas</b><br><span style=\"font-size:21px;color:#1f2430\">«Bem», «razoável», «pouco»: não se podem observar.</span>",
